export interface Request {
  path: string;
}

export interface Reply {
  send(body: unknown): void;
}

export type Handler = (request: Request, reply: Reply, next: () => void) => void;

export interface App {
  get(path: string, handler: Handler): this;
  all(path: string, handler: Handler): this;
  /** Serves `child` under `prefix`: another app, or a handler for every path below it. */
  use(prefix: string, child: App | Handler): this;
}

declare function web(): App;
export default web;
